-- Blueprint: SCD2 Dimension (SCD2Dimension)
-- Codegen engine: CodegenOpEngine

{{ config(
    materialized='incremental',
    incremental_strategy='merge',
    on_schema_change='append_new_columns',
    unique_key=['loanmasterscd2_sk', 'effective_from'],
    alias='msp_loan_master_ingestion__loanmasterscd2',
    schema='pulse_gold',
    catalog_name='pulse_iceberg',
    storage_uri='gs://pulse-home-lending-dev-lake/servicing/msp/msp-loan-master-ingestion/silver',
    tags=['pulse', 'msp_loan_master_ingestion', 'loanmasterscd2', 'intermediate', 'op_engine']
) }}

-- SCD2 Type-2 dimension — managed-Iceberg dbt INCREMENTAL MERGE model (ADR 0026 option 2).
-- First run opens every current source row. Incremental runs close the prior version of a
-- tracked-changed natural key (is_current=false, effective_to = business_date - 1 day) and
-- open a new current version; unchanged rows are untouched (idempotent). The merge keys on
-- the version grain (surrogate + effective_from). Business date = env_var(PULSE_BUSINESS_DATE).
with scd2_source_raw as (
    select
        to_hex(md5(concat(coalesce(cast(src.loan_id as string), '')))) as loanmasterscd2_sk,
        src.*
    from {{ ref('int__servicing__validateloanmaster') }} as src
)
, scd2_source as (
    select *
    from scd2_source_raw as src_dedup
    qualify row_number() over (partition by src_dedup.loanmasterscd2_sk order by to_json_string(src_dedup) desc) = 1
)
{% if is_incremental() %}
, scd2_current as (
    select *
    from {{ this }} as cur
    where is_current = true
    qualify row_number() over (partition by cur.loanmasterscd2_sk order by cur.effective_from desc, to_json_string(cur) desc) = 1
)
, scd2_changed_keys as (
    select c.loanmasterscd2_sk as loanmasterscd2_sk
    from scd2_current c
    join scd2_source s on s.loanmasterscd2_sk = c.loanmasterscd2_sk
    where to_hex(md5(concat(coalesce(cast(s.loan_status as string), ''), '|', coalesce(cast(s.current_upb as string), ''), '|', coalesce(cast(s.interest_rate as string), ''), '|', coalesce(cast(s.next_payment_due_date as string), ''), '|', coalesce(cast(s.escrow_balance as string), ''), '|', coalesce(cast(s.months_delinquent as string), '')))) != to_hex(md5(concat(coalesce(cast(c.loan_status as string), ''), '|', coalesce(cast(c.current_upb as string), ''), '|', coalesce(cast(c.interest_rate as string), ''), '|', coalesce(cast(c.next_payment_due_date as string), ''), '|', coalesce(cast(c.escrow_balance as string), ''), '|', coalesce(cast(c.months_delinquent as string), ''))))
)
, scd2_closed as (
    select
        c.loanmasterscd2_sk,
        c.* except(loanmasterscd2_sk, effective_from, effective_to, is_current),
        c.effective_from as effective_from,
        date_sub(cast('{{ env_var("PULSE_BUSINESS_DATE") }}' as date), interval 1 day) as effective_to,
        false as is_current
    from scd2_current c
    join scd2_changed_keys k on k.loanmasterscd2_sk = c.loanmasterscd2_sk
)
, scd2_opened as (
    select
        s.loanmasterscd2_sk,
        s.* except(loanmasterscd2_sk),
        cast('{{ env_var("PULSE_BUSINESS_DATE") }}' as date) as effective_from,
        cast('9999-12-31' as date) as effective_to,
        true as is_current
    from scd2_source s
    left join scd2_current c on c.loanmasterscd2_sk = s.loanmasterscd2_sk
    where c.loanmasterscd2_sk is null
       or s.loanmasterscd2_sk in (select loanmasterscd2_sk from scd2_changed_keys)
)
select * from scd2_closed
union all
select * from scd2_opened
{% else %}
    select
        s.loanmasterscd2_sk,
        s.* except(loanmasterscd2_sk),
        cast('{{ env_var("PULSE_BUSINESS_DATE") }}' as date) as effective_from,
        cast('9999-12-31' as date) as effective_to,
        true as is_current
from scd2_source s
{% endif %}
